/* Mass Effect (PC, 2008) settings for the Android port.
 * Replaces MassEffectConfig.exe: same engine keys ([WinDrv.WindowsClient] etc.), plus port options.
 *
 * Files (Windows view -> host via VFS):
 *   <game>/BioGame/Config/Default{Engine,Game,Input}.ini     shipped defaults (never modified on disk)
 *   <docs>/BioWare/Mass Effect/Config/BIO{Engine,Game,Input}.ini   user files generated by the game
 *   <docs>/BioWare/Mass Effect/Config/me1port_overrides.ini   our overrides; the runtime applies them when
 *        the game reads Default*.ini, so the first generated BIO*.ini already contains them (no timestamp change,
 *        so the engine's [IniVersion] check does not see an "outdated" ini)
 *   <docs>/BioWare/Mass Effect/me1port.ini                    port-only options (renderer, FPS cap, touch)
 */
#pragma once
#include <stddef.h>
enum { SF_ENGINE, SF_GAME, SF_INPUT, SF_PORT, SF_COUNT };
typedef enum { ST_BOOL, ST_BOOL01, ST_INT, ST_FLOAT, ST_ENUM, ST_RES, ST_STR } SetType;
typedef struct { const char* value; const char* label; } SetChoice;
typedef struct {
    const char* id; const char* group; const char* label; const char* help;
    int file; const char* section; const char* key; const char* key2;   /* key2: Y for resolution / mirrored key */
    const char* section2;                                               /* optional second section with the same key */
    SetType type; const char* def; double min, max; const SetChoice* choices;
} SettingDef;
extern const SettingDef me1_settings[];
extern const int me1_nsettings;

typedef struct {
    const char* id; const char* label; const char* help;
    const char* const* kv;   /* "id=value" pairs, NULL-terminated */
} SettingPreset;
extern const SettingPreset me1_presets[];
extern const int me1_npresets;

#define ME1_MAXSET 64
typedef struct {
    char game_dir[512], docs_dir[512];
    char value[ME1_MAXSET][96];
    char source[ME1_MAXSET][16];   /* "user", "override", "default", "builtin" */
    int dirty[ME1_MAXSET];
} ME1Config;

const SettingDef* me1cfg_find(const char* id, int* index);
int   me1cfg_load(ME1Config* c, const char* game_dir, const char* docs_dir);
/* Refresh values changed externally while preserving unsaved local edits. */
int   me1cfg_refresh_clean(ME1Config* c);
int   me1cfg_set(ME1Config* c, const char* id, const char* value, char* err, size_t errcap);   /* 0 ok */
int   me1cfg_preset(ME1Config* c, const char* preset, char* err, size_t errcap);
int   me1cfg_reset(ME1Config* c);                       /* back to Default*.ini values */
/* automatic preset (launcher "Авто"): device -> tier 0..4 (minimal, low, medium, high, ultra) + 16:9 resolution
 * capped by the screen + FPS cap; report = one Russian line for the UI */
typedef struct {
    const char* gpu;     /* GL_RENDERER, e.g. "Mali-G52 MC2", "Adreno (TM) 750" */
    const char* soc;     /* ro.soc.model / ro.board.platform / Build.HARDWARE, e.g. "MT6769", "SM8650", "kalama" */
    int ram_mb, cores, max_mhz, screen_w, screen_h;   /* 0 = unknown */
} ME1Device;
int   me1cfg_classify(const ME1Device* d, char* report, size_t cap, int* fps, char* res, size_t rescap);   /* -> tier */
int   me1cfg_auto(ME1Config* c, const ME1Device* d, char* report, size_t cap);   /* applies; -> tier or -1 */
/* Opt-in next-session resolution adaptation. Returns 1 changed, 0 no change, -1 error. */
int   me1cfg_adapt_resolution(ME1Config* c, char* msg, size_t cap);
int   me1cfg_save(ME1Config* c, char* msg, size_t cap); /* 0 ok */
char* me1cfg_dump(const ME1Config* c);                  /* malloc'd "id=value\tsource\n" lines */
char* me1cfg_schema_json(void);                         /* malloc'd JSON for UIs */
void  me1cfg_paths(const char* game_dir, const char* docs_dir, int file, char* user_ini, char* default_ini, size_t cap);
/* runtime hook: patch the contents of Default<Name>.ini (Name = Engine/Game/Input) with the overrides.
 * returns 1 and a malloc'd buffer if anything changed. */
int   me1cfg_patch_default(const char* docs_dir, const char* ini_name, const void* in, size_t n, void** out, size_t* outn);
int   me1cfg_port_get(const char* docs_dir, const char* id, char* out, size_t cap);   /* read port option for the runtime */
